 const esc=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
 const piloText=value=>esc(String(value??'').replace(/^#{1,6}\s*/gm,'').replace(/\*\*/g,'').trim()).replace(/\n/g,'<br>');
 function localPiloAnswer(question,sources=[]){
  const q=String(question||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
  if(/\bfacture/.test(q)&&!/(cii|ubl|xml|factur-x|factur x|facturation electronique)/.test(q)&&/(comment|creer|faire|finaliser|valider|enregistrer)/.test(q))return`Pour créer une facture dans Piloz :\n1. Ouvrez Ventes > Factures.\n2. Cliquez sur « Créer une facture ».\n3. Sélectionnez le client.\n4. Ajoutez les articles ou services et vérifiez les prix, la TVA, les dates et l’échéance.\n5. Enregistrez le brouillon, ou cliquez sur « Finaliser la facture » quand tout est correct.\n\nLe client est obligatoire. Après finalisation, la facture reçoit son numéro définitif et une correction se fait avec un avoir.`;
  const source=sources[0]||{},raw=String(source.excerpt||source.summary||'');
  const steps=raw.match(/##\s*(?:Étapes|Explication et étapes)\s+([\s\S]*?)(?=\s+##|$)/i)?.[1]||source.summary||raw;
  return String(steps||'Pilo est momentanément indisponible. Reformulez votre demande ou créez un ticket si le problème persiste.').replace(/^#{1,6}\s*/gm,'').replace(/\*\*/g,'').replace(/\s+/g,' ').trim();
 }
